<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';import TencentMap from './TencentMap.vue';import {getStudio,type StudioPayload} from './content-studio-api';import type {MapPlace} from '../../shared/coordinates';
const payload=ref<StudioPayload|null>(null),selected=ref('');onMounted(async()=>payload.value=await getStudio());
const items=computed<MapPlace[]>(()=>Object.values(payload.value?.document.places||{}).map(p=>({code:p.id,name:p.name.zh,latitude:p.coordinates.latitude,longitude:p.coordinates.longitude,public_level:'P1',current_status:p.publicStatus,map_display_role:'pin',parent_code:null,ancestor_codes:[],coordinate_id:'studio',updated_at:payload.value?.updatedAt||'',category_name:p.category,region:p.region.zh,has_pending:false})));
</script>
<template><div class="workspace-page studio-page"><div class="workspace-title"><div><p class="kicker">地图</p><h1>地图可视化维护</h1><p>点击点位打开地点。地图名称与优先级在地点编辑页维护；坐标修改走安全确认流程。</p></div><RouterLink class="button primary-action" to="/places">＋ 新增地点</RouterLink></div><TencentMap :items="items" @select="selected=$event"/><div v-if="selected" class="map-selected-card"><strong>{{payload?.document.places[selected]?.name.zh}}</strong><span>{{selected}}</span><RouterLink class="button primary-action" :to="`/studio/places/${selected}`">编辑地点内容</RouterLink><RouterLink class="button quiet" :to="`/places/${selected}?relocate=1`">安全编辑位置</RouterLink></div></div></template>
